"""Evidence is generated by trusted host orchestration, never parsed from LLM text."""

from datetime import datetime, timezone
from typing import Annotated, Literal, Self
from uuid import uuid4

from pydantic import AwareDatetime, BaseModel, ConfigDict, Field, StringConstraints, model_validator
from workflow_studio.storage.paths import canonical_run_id

Status = Literal["passed", "failed", "error", "timeout", "not_run"]
Digest = Annotated[str, StringConstraints(pattern=r"^[0-9a-f]{64}$")]
VALIDATOR_VERSION = "isolated-cli-v1"
COMMAND = ("python", "-I", "-B", "-c", "trusted entry bootstrap")


class ValidationLimits(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, strict=True)
    case_seconds: float = Field(default=5.0, ge=0.1, le=30, allow_inf_nan=False)
    total_seconds: float = Field(default=60.0, ge=1, le=300, allow_inf_nan=False)
    max_output_bytes: int = Field(default=16384, ge=1024, le=65536)
    max_cases: int = Field(default=16, ge=1, le=32)


class CaseResult(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, hide_input_in_errors=True)
    case_id: str = Field(pattern=r"^[a-z][a-z0-9-]{0,63}$")
    status: Status
    reason: Literal["matched", "assertion_failed", "program_exit", "invalid_json", "output_limit", "resource_limit", "deadline", "cancelled", "runtime_error", "cleanup_failed", "storage_mismatch"]
    exit_code: int | None = Field(default=None, strict=True)
    elapsed_seconds: float = Field(ge=0, allow_inf_nan=False)

    @model_validator(mode="after")
    def executed_pass(self) -> Self:
        if self.status == "passed" and (self.exit_code != 0 or self.reason != "matched"):
            raise ValueError("case_pass_requires_successful_execution")
        return self


class ValidationReport(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True, hide_input_in_errors=True)
    report_id: str = Field(default_factory=lambda: str(uuid4()))
    run_id: str
    artifact_digest: Digest
    context_digest: Digest
    suite_id: str = Field(pattern=r"^[a-z][a-z0-9-]{0,63}$")
    suite_digest: Digest
    validator_version: Literal["isolated-cli-v1"] = VALIDATOR_VERSION
    environment: str = Field(default="unavailable", max_length=256)
    command: tuple[str, ...] = COMMAND
    status: Status
    reason: Literal["finished", "backend_unavailable", "image_unconfigured", "unsupported_dependencies", "unsupported_layout", "manual_required", "no_cases", "case_limit", "runtime_error", "deadline", "cancelled"]
    cases: tuple[CaseResult, ...] = Field(default=(), max_length=32)
    expected_cases: int = Field(ge=0, le=32, strict=True)
    limits: ValidationLimits
    started_at: AwareDatetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    elapsed_seconds: float = Field(ge=0, allow_inf_nan=False)

    @model_validator(mode="after")
    def valid_evidence(self) -> Self:
        canonical_run_id(self.run_id)
        canonical_run_id(self.report_id)
        if self.command != COMMAND or len({item.case_id for item in self.cases}) != len(self.cases):
            raise ValueError("invalid_validation_command_or_case_ids")
        if len(self.cases) > self.expected_cases:
            raise ValueError("too_many_case_results")
        if self.status == "passed" and (not self.cases or len(self.cases) != self.expected_cases or any(item.status != "passed" for item in self.cases) or self.reason != "finished" or self.environment == "unavailable"):
            raise ValueError("validation_pass_requires_complete_execution")
        if self.status == "not_run" and self.cases:
            raise ValueError("unexecuted_report_cannot_claim_cases")
        return self
